 * License: Open Source (TailwindFlex community)
 */
import React from "react";

export function LArtDeCoder() {
  return (
    <div dangerouslySetInnerHTML={{ __html: "<!DOCTYPE html>
<html lang="fr" class="dark">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Omer Design Section</title>

    <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@300;400;600;800&display=swap" rel="stylesheet">

    <style>
        body {
            background-color: #030712; /* Noir bleuté très profond */
            color: #fff;
            font-family: 'Plus Jakarta Sans', sans-serif;
            overflow-x: hidden;
        }

        /* --- ARRIÈRE-PLAN ANIMÉ --- */
        .bg-blob {
            position: fixed;
            width: 500px;
            height: 500px;
            border-radius: 50%;
            background: radial-gradient(circle, rgba(29, 78, 216, 0.15) 0%, rgba(3, 7, 18, 0) 70%);
            filter: blur(80px);
            z-index: -1;
            animation: blob-float 20s infinite alternate;
        }

        @keyframes blob-float {
            from { transform: translate(-20%, -20%) scale(1); }
            to { transform: translate(30%, 30%) scale(1.1); }
        }

        /* --- CADRE IMAGE LIQUIDE --- */
        .liquid-frame {
            position: relative;
            width: 280px;
            height: 280px;
            padding: 15px;
            background: rgba(255, 255, 255, 0.03);
            backdrop-filter: blur(10px);
            border: 1px solid rgba(255, 255, 255, 0.08);
            box-shadow: 0 20px 50px rgba(0, 0, 0, 0.3);
            animation: morph 8s DOMAIN_ANIM_EASE infinite;
        }

        .liquid-frame img {
            width: 100%;
            height: 100%;
            object-cover: cover;
            animation: morph 8s DOMAIN_ANIM_EASE infinite;
        }

        /* Aura lumineuse bleue derrière le cadre */
        .liquid-frame::before {
            content: '';
            position: absolute;
            inset: -20px;
            background: radial-gradient(circle, rgba(59, 130, 246, 0.4) 0%, rgba(3, 7, 18, 0) 70%);
            border-radius: inherit;
            z-index: -1;
            filter: blur(20px);
        }

        @keyframes morph {
            0%, 100% { border-radius: 60% 40% 30% 70% / 60% 30% 70% 40%; }
            50% { border-radius: 30% 60% 70% 30% / 50% 60% 30% 60%; }
        }

        /* --- EFFETS DE RÉVÉLATION AU SCROLL --- */
        .reveal {
            opacity: 0;
            transform: translateY(40px);
            transition: all 1s cubic-bezier(0.22, 1, 0.36, 1);
        }

        .reveal.active {
            opacity: 1;
            transform: translateY(0);
        }

        /* Parallaxe doux pour l'image */
        .parallax-img {
            transition: transform 0.2s ease-out;
        }

    </style>
</head>
<body class="antialiased">

    <div class="bg-blob" style="top: 10%; left: -10%;"></div>
    <div class="bg-blob" style="bottom: -10%; right: -10%; background: radial-gradient(circle, rgba(147, 51, 234, 0.1) 0%, rgba(3, 7, 18, 0) 70%);"></div>

    <div class="h-[50vh]"></div>

    <section class="max-w-7xl mx-auto px-6 py-20 md:py-32 grid grid-cols-1 md:grid-cols-12 gap-12 md:gap-16 items-center">

        <div class="md:col-span-7 flex flex-col gap-6 reveal">
            <div class="flex items-center gap-3">
                <span class="w-12 h-[2px] bg-blue-600"></span>
                <span class="text-blue-500 font-bold tracking-widest text-sm uppercase">Creative Developer</span>
            </div>

            <h2 class="text-4xl md:text-6xl font-black leading-tight tracking-tighter">
                L'art de coder des <span class="bg-gradient-to-r from-blue-400 to-blue-600 bg-clip-text text-transparent">expériences fluides</span>.
            </h2>

            <p class="text-gray-400 text-lg md:text-xl leading-relaxed max-w-2xl">
                Je m'appelle Omer, je fusionne le design thinking avec un code propre pour bâtir des interfaces numériques intuitives et engageantes. Spécialiste de <span class="text-white font-semibold">Tailwind CSS</span> et des micro-interactions.
            </p>

            <div class="flex gap-4 mt-4">
                <button class="bg-blue-600 hover:bg-blue-700 text-white px-8 py-4 rounded-full font-bold text-sm transition-all active:scale-95 shadow-lg shadow-blue-900/50">
                    Découvrir mes travaux
                </button>
                <button class="bg-white/5 hover:bg-white/10 text-white px-8 py-4 rounded-full font-bold text-sm border border-white/10 transition-all">
                    Me contacter
                </button>
            </div>
        </div>

        <div class="md:col-span-5 flex justify-center md:justify-end reveal" style="transition-delay: 0.2s;">
            <div class="parallax-img">
                <div class="liquid-frame">
                    <img src="https://lh3.googleusercontent.com/a/ACg8ocKtpueB00ZdmmbwHuEtYEPdrXJPJfNiBWQk1dOtCeuvGkNyEfyz=s96-c" alt="Omer Profile" class="object-cover">
                </div>
            </div>
        </div>

    </section>

    <div class="h-[100vh]"></div>


</body>
</html>" }} />
  );
}
